mapper.select:
SELECT COUNT(*) FROM  r JOIN prop_sku s ON s.id=r.sku_id LEFT JOIN prop_sn_instance sn ON sn.id=r.sn_id WHERE 1=1
 AND r.sku_id=#{reservationQueryDTO.skuId}
 AND r.sn_id=#{reservationQueryDTO.snId}
 AND reservation_status=#{reservationQueryDTO.status}
 AND occupy_start_date<=#{reservationQueryDTO.end} AND occupy_end_date>=#{reservationQueryDTO.start}
 AND (LOCATE(#{reservationQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{reservationQueryDTO.keyword},s.prop_name)>0 OR LOCATE(#{reservationQueryDTO.keyword},CONVERT(sn.sn_code USING utf8mb4) COLLATE utf8mb4_bin)>0)

SELECT r.id, r.checkout_batch_id, r.checkout_batch_item_snapshot_id, r.expires_at, r.occupy_end_date, r.occupy_start_date, r.quantity, r.rental_end_date, r.rental_order_id, r.rental_order_item_id, r.rental_start_date, r.reservation_status, r.sku_id, r.sn_id, r.source_id, r.source_type, r.updated_at,s.sku_code,s.prop_name,sn.sn_code FROM  r JOIN prop_sku s ON s.id=r.sku_id LEFT JOIN prop_sn_instance sn ON sn.id=r.sn_id WHERE 1=1
 AND r.sku_id=#{reservationQueryDTO.skuId}
 AND r.sn_id=#{reservationQueryDTO.snId}
 AND reservation_status=#{reservationQueryDTO.status}
 AND occupy_start_date<=#{reservationQueryDTO.end} AND occupy_end_date>=#{reservationQueryDTO.start}
 AND (LOCATE(#{reservationQueryDTO.keyword},CONVERT(s.sku_code USING utf8mb4) COLLATE utf8mb4_bin)>0 OR LOCATE(#{reservationQueryDTO.keyword},s.prop_name)>0 OR LOCATE(#{reservationQueryDTO.keyword},CONVERT(sn.sn_code USING utf8mb4) COLLATE utf8mb4_bin)>0)
 ORDER BY r.created_at DESC,r.id DESC LIMIT #{reservationQueryDTO.limit} OFFSET #{reservationQueryDTO.offset}

SELECT  FROM inventory_reservation
WHERE reservation_status IN ('released','expired','cancelled','completed') AND updated_at<=#{before}
ORDER BY id LIMIT 100 FOR UPDATE SKIP LOCKED

mapper.update:
UPDATE inventory_reservation SET reservation_status=IF(#{outbound},'renting','completed'),
    occupy_start_date=IF(#{outbound},LEAST(occupy_start_date,DATE(#{at})),occupy_start_date),version=version+1,updated_at=#{at}
    WHERE id=#{id} AND rental_order_id=#{orderId} AND reservation_status=#{before}

mapper.select:
SELECT EXISTS(SELECT 1 FROM inventory_reservation WHERE sn_id=#{snId} AND id<>#{id}
    AND reservation_status IN ('held','paid_locked','renting','overdue_holding','disputed_holding') AND occupy_start_date<=#{end}
    AND >=#{start})
